Here is the commit message:
nouveau/gsp: drop WARN_ON in ACPI probes

These WARN_ONs seem to trigger a lot, and we don't seem to have a
plan to fix them, so just drop them, as they are most likely
harmless.

Cc: stable@vger.kernel.org
Fixes: 176fdcbddfd2 ("drm/nouveau/gsp/r535: add support for booting GSP-RM")
Signed-off-by: Dave Airlie <airlied@redhat.com>
Link: https://patch.msgid.link/20241121014601.229391-1-airlied@gmail.com
Signed-off-by: Danilo Krummrich <dakr@kernel.org>

Here is the root cause:
The ACPI firmware methods (_CAPS, _JT, _DOD) are returning data with types or buffer lengths that do not match the driver's expectations (e.g., ACPI_TYPE_BUFFER with length != 4, or ACPI_TYPE_PACKAGE with count exceeding limit). These mismatches are benign but caused the WARN_ON macros to trigger frequently, producing unnecessary kernel warnings. The patch removes the WARN_ONs to suppress these spurious alerts, as the condition is harmless and not indicative of a real error.

Here is the patch:
 #if defined(CONFIG_ACPI) && defined(CONFIG_X86)
 void
 r535_gsp_acpi_caps(acpi_handle handle, CAPS_METHOD_DATA *caps)
 {
 	const guid_t NVOP_DSM_GUID =
 		GUID_INIT(0xA486D8F8, 0x0BDA, 0x471B,
 			  0xA7, 0x2B, 0x60, 0x42, 0xA6, 0xB5, 0xBE, 0xE0);
 	u64 NVOP_DSM_REV = 0x00000100;
 	union acpi_object argv4 = {
 		.buffer.type    = ACPI_TYPE_BUFFER,
 		.buffer.length  = 4,
 	}, *obj;

 	caps->status = 0xffff;

 	if (!acpi_check_dsm(handle, &NVOP_DSM_GUID, NVOP_DSM_REV, BIT_ULL(0x1a)))
 		return;

 	argv4.buffer.pointer = kmalloc(argv4.buffer.length, GFP_KERNEL);
 	if (!argv4.buffer.pointer)
 		return;

 	obj = acpi_evaluate_dsm(handle, &NVOP_DSM_GUID, NVOP_DSM_REV, 0x1a, &argv4);
 	if (!obj)
 		goto done;

-	if (WARN_ON(obj->type != ACPI_TYPE_BUFFER) ||
-	    WARN_ON(obj->buffer.length != 4))
+	if (obj->type != ACPI_TYPE_BUFFER ||
+	    obj->buffer.length != 4)
 		goto done;

 	caps->status = 0;
 	caps->optimusCaps = *(u32 *)obj->buffer.pointer;

 done:
 	ACPI_FREE(obj);

 	kfree(argv4.buffer.pointer);
 }

 void
 r535_gsp_acpi_jt(acpi_handle handle, JT_METHOD_DATA *jt)
 {
 	const guid_t JT_DSM_GUID =
 		GUID_INIT(0xCBECA351L, 0x067B, 0x4924,
 			  0x9C, 0xBD, 0xB4, 0x6B, 0x00, 0xB8, 0x6F, 0x34);
 	u64 JT_DSM_REV = 0x00000103;
 	u32 caps;
 	union acpi_object argv4 = {
 		.buffer.type    = ACPI_TYPE_BUFFER,
 		.buffer.length  = sizeof(caps),
 	}, *obj;

 	jt->status = 0xffff;

 	argv4.buffer.pointer = kmalloc(argv4.buffer.length, GFP_KERNEL);
 	if (!argv4.buffer.pointer)
 		return;

 	obj = acpi_evaluate_dsm(handle, &JT_DSM_GUID, JT_DSM_REV, 0x1, &argv4);
 	if (!obj)
 		goto done;

-	if (WARN_ON(obj->type != ACPI_TYPE_BUFFER) ||
-	    WARN_ON(obj->buffer.length != 4))
+	if (obj->type != ACPI_TYPE_BUFFER ||
+	    obj->buffer.length != 4)
 		goto done;

 	jt->status = 0;
 	jt->jtCaps = *(u32 *)obj->buffer.pointer;
 	jt->jtRevId = (jt->jtCaps & 0xfff00000) >> 20;
 	jt->bSBIOSCaps = 0;

 done:
 	ACPI_FREE(obj);

 	kfree(argv4.buffer.pointer);
 }


 void
 r535_gsp_acpi_dod(acpi_handle handle, DOD_METHOD_DATA *dod)
 {
 	acpi_status status;
 	struct acpi_buffer output = { ACPI_ALLOCATE_BUFFER, NULL };
 	union acpi_object *_DOD;

 	dod->status = 0xffff;

 	status = acpi_evaluate_object(handle, "_DOD", NULL, &output);
 	if (ACPI_FAILURE(status))
 		return;

 	_DOD = output.pointer;

-	if (WARN_ON(_DOD->type != ACPI_TYPE_PACKAGE) ||
-	    WARN_ON(_DOD->package.count > ARRAY_SIZE(dod->acpiIdList)))
+	if (_DOD->type != ACPI_TYPE_PACKAGE ||
+	    _DOD->package.count > ARRAY_SIZE(dod->acpiIdList))
 		return;

 	for (int i = 0; i < _DOD->package.count; i++) {
 		if (WARN_ON(_DOD->package.elements[i].type != ACPI_TYPE_INTEGER))
 			return;

 		dod->acpiIdList[i] = _DOD->package.elements[i].integer.value;
 		dod->acpiIdListLen += sizeof(dod->acpiIdList[0]);
 	}

 	dod->status = 0;
 	kfree(output.pointer);
 }
 #endif


